#######################
# 这样可以找到另一个拥有完全相同的类的用户
#返回它所拥有的用户数，如果该用户数大于1，则无需放入标记类中
def find_same_class(user_num,dict_class,current_user):
    
    for i in range(user_num):
        a = list(dict_class[i][i])
        if (a.count(dict_class[current_user][current_user])) > 0 and i!=current_user:
            break
    
    
    return len(dict_class[i][i])
